/* Immutable, versioned transport. Import validates structure/domain, not authenticity. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ExtendedRecord=api;})(globalThis,()=>{
'use strict';
const schema='isac-extended-teaching-record-v1';
const statuses=['converged','numerical_rejection','numerical_failure','iteration_cap','elapsed_work_cap','cancelled','invalid_input','proven_infeasible'];
const freeze=x=>{if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;};
function assert(ok,message){if(!ok)throw Error(message);}
function matrix(x,r,c){assert(x&&Object.keys(x).sort().join(',')==='imag,real','Packed matrix schema');for(const part of ['real','imag'])assert(Array.isArray(x[part])&&x[part].length===r&&x[part].every(row=>Array.isArray(row)&&row.length===c&&row.every(Number.isFinite)),'Matrix dimensions/values');}
function input(x){assert(x&&Object.keys(x).sort().join(',')===['Nt','Nr','K','L','powerMw','communicationNoiseMw','radarNoiseMw','gammaDb','H'].sort().join(','),'Input schema');assert([4,6].includes(x.Nt)&&x.Nr===x.Nt+4&&x.K===2&&x.L===30&&x.powerMw===1000&&x.communicationNoiseMw===1&&x.radarNoiseMw===1&&Number.isFinite(x.gammaDb)&&x.gammaDb>=0&&x.gammaDb<=20,'Outside supported domain');matrix(x.H,2,x.Nt);for(let j=0;j<2;j++)for(let i=0;i<x.Nt;i++)assert(Math.hypot(x.H.real[j][i],x.H.imag[j][i])<=10,'Channel magnitude exceeds 10');return x;}
function finiteTree(x,depth=0){assert(depth<40,'Record nesting limit');if(typeof x==='number')assert(Number.isFinite(x),'Nonfinite value');if(x&&typeof x==='object')for(const [k,v] of Object.entries(x)){assert(!['__proto__','prototype','constructor'].includes(k),'Unsafe key');finiteTree(v,depth+1);}}
function validate(x){finiteTree(x);assert(x&&Object.keys(x).sort().join(',')==='createdAt,input,record,runId,schema','Record envelope schema');assert(x.schema===schema&&typeof x.runId==='string'&&x.runId.length>0&&x.runId.length<100&&typeof x.createdAt==='string'&&Number.isFinite(Date.parse(x.createdAt)),'Record metadata');input(x.input);const r=x.record;assert(r&&r.version==='crb-extended-drs-v0.1-numerical'&&statuses.includes(r.status),'Solver version/status');assert(r.physicalGate&&typeof r.physicalGate.passed==='boolean','Missing physical gate');if(r.status!=='invalid_input'){assert(r.input&&r.options&&Number.isInteger(r.iterations)&&r.iterations>=0&&Array.isArray(r.trace),'Incomplete solver record');const o=r.options,keys=['rho','linearWeight','relaxation','memory','maxIterations','maxElapsedMs','tolerance','recordEvery'];assert(Object.keys(o).sort().join(',')===keys.sort().join(',')&&keys.every(k=>Number.isFinite(o[k])),'Options schema');assert(o.rho>=1e-3&&o.rho<=1000&&o.linearWeight>=.1&&o.linearWeight<=100&&o.relaxation>0&&o.relaxation<2&&Number.isInteger(o.memory)&&o.memory>=0&&o.memory<=20&&Number.isInteger(o.maxIterations)&&o.maxIterations>0&&o.maxIterations<=200000&&o.maxElapsedMs>0&&o.maxElapsedMs<=600000&&o.tolerance>=1e-11&&o.tolerance<=1e-6&&Number.isInteger(o.recordEvery)&&o.recordEvery>0,'Options domain');}if(r.input)assert(JSON.stringify(r.input)===JSON.stringify(x.input),'Input mismatch');const n=x.input.Nt;for(const k of ['relaxedR','epigraphTNormalized'])if(r[k])matrix(r[k],n,n);if(r.Wks){assert(r.Wks.length===3,'Covariance count');r.Wks.forEach(q=>matrix(q,n,n));}for(const pair of [[r.Wc,n,2],[r.Wa,n,n],[r.baseline?.Wc,n,2],[r.baseline?.Wa,n,n]])if(pair[0])matrix(...pair);
function metrics(m){assert(m&&Number.isFinite(m.powerMw)&&Number.isFinite(m.powerFraction)&&Array.isArray(m.users)&&m.users.length===2,'Metrics schema');for(const u of m.users)for(const k of ['desiredMw','dataInterferenceMw','probingInterferenceMw','sinr','ratioToThreshold'])assert(Number.isFinite(u[k]),'User metric');assert(m.radar&&['regular','singular'].includes(m.radar.status)&&Array.isArray(m.radar.eigenvaluesMw)&&m.radar.eigenvaluesMw.length===n&&m.radar.eigenvaluesMw.every(Number.isFinite),'Radar metric');for(const k of ['traceInversePerMw','normalizedObjective','fullResponseMseBound'])assert(m.radar[k]===null||Number.isFinite(m.radar[k]),'Radar bound');}
if(r.metrics)metrics(r.metrics);if(r.baseline){metrics(r.baseline.metrics);assert(typeof r.baseline.feasible==='boolean','Baseline feasibility');}if(r.status==='converged'||r.status==='numerical_rejection'){assert(r.Wks&&r.relaxedR&&r.Wc&&r.Wa&&r.metrics&&r.baseline&&r.recovery&&r.certificate,'Incomplete solved record');matrix(r.certificate.Z,2*n,2*n);assert(r.certificate.sinrMultipliers?.length===2&&Number.isFinite(r.certificate.relativeGap),'Certificate schema');}assert(!r.physicalGate.passed||r.status==='converged','Contradictory acceptance');return x;}
function parse(text){assert(typeof text==='string'&&text.length<=5000000,'Record exceeds 5 MB');return freeze(validate(JSON.parse(text)));}
function create(runId,rawInput,record){return parse(JSON.stringify({schema,runId,createdAt:new Date().toISOString(),input:rawInput,record}));}
function seeded(nt,seed){let s=seed>>>0;const rnd=()=>{s=(Math.imul(1664525,s)+1013904223)>>>0;return (s+.5)/4294967296;};const gaussian=()=>Math.sqrt(-Math.log(rnd()))*Math.cos(2*Math.PI*rnd());return {real:Array.from({length:2},()=>Array.from({length:nt},gaussian)),imag:Array.from({length:2},()=>Array.from({length:nt},gaussian))};}
class RunGate{constructor(){this.current=null;}begin(id){this.current=id;}clear(){this.current=null;}accept(message){return this.current!==null&&message.runId===this.current;}}
return {schema,freeze,input,parse,create,seeded,RunGate};});
